import { engineFetch } from "@/server/engine/client";
import { can } from "@/server/policy";
import { getPrincipal } from "@/server/session";

// Report exports (R14), generated by the engine from stored results and streamed through.
export async function GET(req: Request, { params }: { params: Promise<{ kind: string }> }) {
  const { kind } = await params;
  const p = await getPrincipal();
  if (!p?.tenantId || !can(p, "ecl.view")) return new Response("Unauthorized", { status: 401 });
  const q = new URL(req.url).searchParams;
  const run = q.get("run") ?? "", cmp = q.get("compare"), fmt = q.get("fmt") === "csv" ? "csv" : "xlsx";
  if (!/^[0-9A-Z]{26}$/.test(run) || (cmp && !/^[0-9A-Z]{26}$/.test(cmp)) || !/^[a-z]{3,12}$/.test(kind)) return new Response("Bad request", { status: 400 });
  const r = await engineFetch(p, `/api/v1/tenants/${p.tenantId}/ecl/runs/${run}/reports/${kind}?fmt=${fmt}${cmp ? `&compare=${cmp}` : ""}`);
  if (!r.ok || !r.body) return new Response((await r.text().catch(() => "")) || "This report isn't available.", { status: r.status || 502 });
  return new Response(r.body, { headers: { "Content-Type": r.headers.get("content-type") ?? "application/octet-stream", "Content-Disposition": r.headers.get("content-disposition") ?? "attachment", "Cache-Control": "private, no-store" } });
}
